import {esc} from './domain.js';
export const PREFS_KEY='orbit.preferences.v1';
export const defaults={workspaceName:'Personal workspace',currency:'USD',theme:'dark',setupComplete:false};
export function loadPreferences(storage=localStorage){
 try{const p=JSON.parse(storage.getItem(PREFS_KEY)||'{}');return {workspaceName:typeof p.workspaceName==='string'&&p.workspaceName.trim()?p.workspaceName.trim().slice(0,60):defaults.workspaceName,currency:['USD','INR','EUR','GBP'].includes(p.currency)?p.currency:defaults.currency,theme:['light','dark'].includes(p.theme)?p.theme:defaults.theme,setupComplete:p.setupComplete===true};}catch{return {...defaults};}
}
export function openSetup({preferences,onFinish,onError}){
 const dialog=document.querySelector('#setup-dialog');let step=0,draft={...preferences};
 const stages=['Welcome','Your workspace','Know your limits','Ready to go'];
 function render(){
  const screens=[
   `<div class="setup-welcome"><img src="./icon.svg" alt="" width="88" height="88"><p class="eyebrow">A HOME FOR ALL YOUR AI ACCOUNTS</p><h2 id="setup-title">Welcome to Orbit.</h2><p>Know what you can use, when it resets, and what renews next. Let’s set up your own workspace.</p></div><div class="setup-benefits"><div><strong>Yours from the start</strong><p>Add your actual accounts. No sample accounts or made-up balances.</p></div><div><strong>Ready without Wi-Fi</strong><p>Track locally, with no sign-in required. Google sync is optional in the web app.</p></div></div>`,
   `<p class="eyebrow">MAKE YOURSELF AT HOME</p><h2 id="setup-title">A few personal touches.</h2><p class="setup-intro">These preferences stay on this device. You can change them later in Settings.</p><div class="form-grid"><label class="field full">Workspace name<input id="setup-name" maxlength="60" value="${esc(draft.workspaceName)}" autocomplete="off"></label><label class="field">Default currency<select id="setup-currency">${['USD','INR','EUR','GBP'].map(c=>`<option ${draft.currency===c?'selected':''}>${c}</option>`).join('')}</select><small>You can choose another currency for each account.</small></label><label class="field">Appearance<select id="setup-theme"><option value="dark" ${draft.theme==='dark'?'selected':''}>Dark</option><option value="light" ${draft.theme==='light'?'selected':''}>Light</option></select></label></div>`,
   `<p class="eyebrow">A MINUTE NOW, MORE CLARITY LATER</p><h2 id="setup-title">Use the numbers your provider shows.</h2><div class="setup-instructions"><div><span>01</span><div><h3>Add an account label and plan</h3><p>Record the provider, tier, and whether it is free, paid, or a trial. Orbit never needs your AI account password.</p></div></div><div><span>02</span><div><h3>Track each limit separately</h3><p>If your provider shows both a 5-hour and weekly limit, add both. Enter the amount used and the next reset time. The tighter limit decides availability.</p></div></div><div><span>03</span><div><h3>Set renewal and expiry dates</h3><p>A billing renewal and the end of a trial are different dates. Enter only what applies to that account.</p></div></div></div><div class="notice">Usage is updated manually. A countdown reaching zero asks you to check the provider; it does not automatically refill your credits.</div>`,
   `<p class="eyebrow">ALL SET</p><h2 id="setup-title">Start with one account.</h2><p class="setup-intro">Your dashboard will grow with you. Add an account now, restore an existing Orbit backup, or open your empty workspace.</p><div class="setup-summary"><span>Workspace<strong>${esc(draft.workspaceName||defaults.workspaceName)}</strong></span><span>Currency<strong>${draft.currency}</strong></span><span>Storage<strong>On this device</strong></span></div><div class="notice">Keep a backup before changing devices or clearing app data. Google sync requires one-time configuration in the web app; desktop and phone builds currently use backup export/import.</div><div class="setup-options"><button class="btn primary" data-setup="finish-add">Add my first account →</button><button class="btn" data-setup="finish-import">Restore an Orbit backup</button><button class="text-btn" data-setup="finish">Open my workspace</button></div>`
  ];
  dialog.innerHTML=`<div class="setup-shell"><header class="setup-top"><a class="brand"><img src="./icon.svg" alt="">orbit</a><span>SETUP · ${step+1} OF 4</span></header><ol class="setup-progress" aria-label="Setup progress">${stages.map((s,i)=>`<li class="${i<=step?'done':''}" ${i===step?'aria-current="step"':''}><span>${i+1}</span>${s}</li>`).join('')}</ol><div class="setup-body">${screens[step]}<p class="form-error" id="setup-error" role="alert"></p></div><footer class="setup-footer">${step?'<button class="btn ghost" data-setup="back">← Back</button>':'<span class="help">Offline-first. No account required.</span>'}${step<3?`<button class="btn primary" data-setup="next">${step===0?'Get started':'Continue'} →</button>`:'<span class="help">You can reopen this guide in Settings.</span>'}</footer></div>`;
  dialog.querySelector('h2')?.setAttribute('tabindex','-1');dialog.querySelector('h2')?.focus();
 }
 function capture(){if(step===1){draft.workspaceName=dialog.querySelector('#setup-name').value.trim()||defaults.workspaceName;draft.currency=dialog.querySelector('#setup-currency').value;draft.theme=dialog.querySelector('#setup-theme').value;}}
 dialog.onclick=event=>{const button=event.target.closest('[data-setup]');if(!button)return;capture();const action=button.dataset.setup;if(action==='next'){step++;render();}else if(action==='back'){step--;render();}else if(action.startsWith('finish')){try{onFinish({...draft,setupComplete:true},action);dialog.close();}catch(error){dialog.querySelector('#setup-error').textContent=error.message;onError?.(error);}}};
 dialog.oncancel=event=>event.preventDefault();
 if(!dialog.open)dialog.showModal();render();
}
export function guidePage(){return `<section class="guide-hero"><p class="eyebrow">YOUR EVERYDAY GUIDE</p><h2>From your first account to your next reset.</h2><p>Everything you need to get started, available offline.</p><button class="btn primary" data-action="setup">Run startup setup again</button></section><div class="guide-grid"><section class="panel"><h3>1. Add your accounts</h3><p>Choose a provider, give the account a useful label, and enter your plan. Email is optional. Do not enter passwords or API keys in notes.</p><button class="text-btn" data-action="add">Add an account →</button></section><section class="panel"><h3>2. Record usage windows</h3><p>Open the provider’s usage page and copy its current values. Use 5 hours for a session window, 168 hours for a weekly window, or enter a custom period. If only a percentage is shown, use 100 as the total and % as the unit.</p><p>Record separate limits for separate models where needed. Accounts with no limits have unknown availability.</p></section><section class="panel"><h3>3. Understand resets</h3><p>Fixed windows follow a schedule. Rolling windows are estimates. When a timer is due, open Update usage and confirm the provider has reset before clearing that window.</p><p>Orbit shows projected fixed resets before an access expiry date. An ongoing subscription without an expiry has no finite reset count.</p></section><section class="panel"><h3>4. Track your subscription</h3><p>Enter the price per billing cycle and whether it is monthly or annual. Annual plans are averaged in the monthly total. Different currencies stay separate.</p><p>Use the expiry field for trial endings or access termination. If ChatGPT and Codex share one subscription, enter its price only once to avoid double-counting.</p></section><section class="panel"><h3>5. Choose what to use next</h3><p>Use next considers your tightest remaining limit, task fit, favorites, near-term resets, and upcoming expiry. Paused, expired, exhausted, or unverified-reset accounts are excluded.</p><p>It uses your recorded numbers. Opening a provider does not switch its signed-in account for you.</p><button class="text-btn" data-view="recommend">See recommendations →</button></section><section class="panel"><h3>6. Back up and move devices</h3><p>Settings → Export workspace creates a JSON backup. Import it on another device to restore accounts and history. Imported data replaces the current workspace after confirmation.</p><p>Backups are unencrypted and include your notes and identifiers. Keep them somewhere you trust. Preferences and Google tokens are not included.</p><button class="text-btn" data-view="settings">Open backup settings →</button></section><section class="panel"><h3>Optional Google sync</h3><p>In the browser or installed web app, open Settings → Google Drive sync. Configure an OAuth client ID once, connect your Google account, then choose Sync now.</p><p>Offline edits stay local. Conflicting edits require choosing a version; download both first if you want to combine them. Tokens expire and may require reconnecting. Native desktop and mobile Google sign-in is not yet available.</p><details><summary>Google Cloud setup steps</summary><ol><li>Create a Google Cloud project and enable Google Drive API.</li><li>Configure the consent screen and add your test users.</li><li>Allow openid, email, and the drive.appdata scope.</li><li>Create a Web application OAuth client and register your app’s exact origin. For development, use http://localhost:4173.</li><li>Paste its public client ID in Settings → Google app setup. Never paste a client secret.</li><li>For public users, complete Google’s publishing requirements. Everyone must use the same app configuration.</li></ol></details></section><section class="panel"><h3>Installing and using offline</h3><p><strong>Windows:</strong> run the installer, or open the portable Orbit executable. The interface is bundled and needs no server.</p><p><strong>Android:</strong> install the provided development APK for personal use. It has not been tested on every phone.</p><p><strong>Web / iPhone:</strong> visit the hosted HTTPS app online once, then install from your browser. In Safari use Share → Add to Home Screen. Offline use depends on retained browser storage.</p><p>Native iPhone and macOS packages still require building and signing on a Mac. This release does not fetch live provider usage or send alerts when closed.</p></section></div>`;}
